calc_js:
"use strict";

// Delegation target for the bridge's end-to-end check. `add` is complete;
// `multiply` is the small change a delegated DSH run is asked to implement.
// The end-to-end test copies this file into a scratch folder, so this reference
// copy stays unimplemented.
function add(a, b) {
  return a + b;
}

function multiply(a, b) {
  throw new Error("multiply is not implemented");
}

module.exports = { add, multiply };

check_js:
"use strict";

// Verification the delegated run must make pass with `node demo/check.js`.
// Exit code 0 means every case passed; 1 prints the failing case and exits.
const { add, multiply } = require("./calc.js");

const cases = [
  ["add keeps working", () => add(2, 3) === 5],
  ["multiply(6, 7) === 42", () => multiply(6, 7) === 42],
  ["multiply(-3, 4) === -12", () => multiply(-3, 4) === -12],
];

let failed = 0;
for (const [name, run] of cases) {
  let ok = false;
  let detail = "";
  try {
    ok = run() === true;
  } catch (error) {
    detail = ` (${error.message})`;
  }
  if (!ok) failed += 1;
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${detail}`);
}

if (failed > 0) {
  console.log(`FAILED ${failed}/${cases.length}`);
  process.exit(1);
}
console.log(`PASSED ${cases.length}/${cases.length}`);
